
import type { MerchantAccountSessionStripeComponent } from './MerchantAccountSessionStripeComponent.js';

export type MerchantAccountSessionStripe = { /** Account session authority for initializing Stripe Connect in the browser. */ "account_session": { /** Short-lived account session client secret to return from fetchClientSecret. Return it only to an authenticated human authorized to manage this merchant. */ "client_secret": string; /** Browser initialization operation to perform. load_connect_and_initialize means call loadConnectAndInitialize with publishableKey and fetchClientSecret. */ "stripe_js_call": "load_connect_and_initialize" | (string & {}); }; /** Authorized Stripe component names and collection options to apply when mounting each component. */ "components": Array<MerchantAccountSessionStripeComponent>; /** Stripe publishable key to pass as publishableKey to loadConnectAndInitialize. */ "publishable_key": string; };
